<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {validSupplementalDetail,type SupplementalIdentity} from '../settlementResponses'
import {useSettlementCommand} from '../settlementCommand'
import {settlementAmount,settlementIssue,supplementalSourceName,supplementalActions,supplementalState} from '../supplemental'
import type {SupplementalBatch,SupplementalDetail} from '../supplemental'
import type {PayChange} from '../payChanges'
import type {PayrollHomeData,PayProfilePage} from '../payrollTypes'
import PhaseStatus from '../components/PhaseStatus.vue'
import StatutoryBalanceTable from '../components/StatutoryBalanceTable.vue'
import WageEventReview from '../components/WageEventReview.vue'
import SupplementalPaymentFields from '../components/SupplementalPaymentFields.vue'
const route=useRoute(),{api,home,base,english,current,store,loading,failure,load}=usePayrollPage(),command=useSettlementCommand(),{locked,uncertain,busy:commandBusy,failure:commandFailure}=command,x=(z:string,e:string)=>english()?e:z,money=(v:string|null|undefined)=>settlementAmount(v,english())
const directory=ref<PayrollHomeData|null>(null),company=ref(String(route.query.companyId||'')),rows=ref<SupplementalBatch[]>([]),requests=ref<PayChange[]>([]),detail=ref<SupplementalDetail|null>(null),requestId=ref(''),proposalId=ref(''),note=ref('')
const employee=ref(String(route.query.employeeId||'')),originMonth=ref(String(route.query.originMonth||''))
const employeeOptions=ref<{id:string;name:string}[]>([])
const people=computed(()=>[...new Map([...employeeOptions.value,...rows.value.map(b=>({id:b.employeeId,name:b.employeeName}))].map(b=>[b.id,b])).values()])
const visibleRows=computed(()=>rows.value.filter(b=>(!employee.value||b.employeeId===employee.value)&&(!originMonth.value||b.originMonth===originMonth.value)))
const approved=computed(()=>requests.value.filter(r=>r.status==='approved'&&r.content.supplemental?.length&&(!employee.value||r.employeeId===employee.value)&&(!originMonth.value||r.content.supplemental.some(p=>p.originMonth===originMonth.value)))),request=computed(()=>approved.value.find(r=>r.id===requestId.value)),proposal=computed(()=>request.value?.content.supplemental?.find(p=>p.id===proposalId.value)),actions=computed(()=>detail.value?supplementalActions(detail.value,directory.value?.employeeId||null):[])
watch(command.errorCode,code=>{if(detail.value&&['SUPPLEMENTAL_SOURCE_CHANGED','AW_CONTEXT_STALE','WORKFORCE_PAYROLL_SOURCE_CHANGED'].includes(code))detail.value.sourceChanged=true})
const canPay=computed(()=>detail.value?.batch.status==='published'&&directory.value?.employeeId!==detail.value.batch.employeeId)
function refresh(){if(locked.value)return;detail.value=null;requests.value=[];rows.value=[];return load(async()=>{const d=await api().get<PayrollHomeData>('/payroll-home'),id=d.companies.find(c=>c.id===company.value)?.id||d.companies[0]?.id||'';if(company.value&&!d.companies.some(c=>c.id===company.value))throw new Error(x('无此公司薪资权限','No payroll access for this company'));const [b,r,p]=id?await Promise.all([api().get<SupplementalBatch[]>('/supplemental-batches?companyId='+id),api().get<PayChange[]>('/pay-change-requests?companyId='+id),api().get<PayProfilePage>('/pay-profiles?companyId='+id)]):[[],[],{employees:[]}];return {d,id,b,r,p}},v=>{employeeOptions.value=Array.isArray(v.p?.employees)?v.p.employees:[];directory.value=v.d;company.value=v.id;rows.value=v.b;requests.value=v.r;requestId.value='';proposalId.value=''})}
function open(id:string){if(locked.value)return;detail.value=null;return load(()=>api().get<SupplementalDetail>('/supplemental-batches/'+id),v=>{if(v.batch.companyId!==company.value)throw new Error('Company mismatch');detail.value=v})}
function accept(v:SupplementalDetail){detail.value=v;rows.value=[v.batch,...rows.value.filter(r=>r.id!==v.batch.id)];note.value=''}
const identity=(b:SupplementalBatch):SupplementalIdentity=>({id:b.id,companyId:b.companyId,employeeId:b.employeeId,proposalId:b.proposal.id,requestId:b.approval.requestId,revision:b.approval.revision,hash:b.approval.hash})
function create(){if(!request.value||!proposal.value||locked.value)return;const r=request.value,p=proposal.value,id=crypto.randomUUID(),expected={id,companyId:company.value,employeeId:r.employeeId!,proposalId:p.id,requestId:r.id,revision:r.revision,hash:r.hash};return command.run<SupplementalDetail>('/supplemental-batches/'+id,{commandId:crypto.randomUUID(),expectedVersion:0,companyId:company.value,employeeId:r.employeeId,requestId:r.id,revision:r.revision,hash:r.hash,proposalId:proposal.value.id},'put',v=>validSupplementalDetail(v,expected),accept)}
function action(verb:string){if(!detail.value||!actions.value.includes(verb)||locked.value)return;const b=detail.value.batch;return command.run<SupplementalDetail>(`/supplemental-batches/${b.id}/actions`,{commandId:crypto.randomUUID(),expectedVersion:b.version,action:verb,expectedFingerprint:b.calculation?.sourceFingerprint||null,note:note.value.trim()},'post',v=>validSupplementalDetail(v,identity(b)),accept)}
function payment(id:string,body:Record<string,unknown>){if(!canPay.value||!detail.value||locked.value)return;const expected=identity(detail.value.batch);return command.run<SupplementalDetail>(`/supplemental-batches/${detail.value.batch.id}/payments/${id}`,body,'put',v=>validSupplementalDetail(v,expected),accept)}
const actionName=(a:string)=>({calculate:x('计算补发','Calculate supplemental'),confirm:x('确认并冻结补发','Confirm and freeze supplemental'),publish:x('发布补发工资单','Publish supplemental payslip'),void:x('作废补发批次','Void supplemental batch')}[a]||a)
onMounted(async()=>{await refresh();const id=String(route.query.batchId||'');if(id&&rows.value.some(b=>b.id===id))await open(id)})
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{x('独立补发工资','Supplemental payroll')}}</h2><button :disabled="locked||loading" @click="refresh">{{x('刷新补发工作台','Refresh supplemental workbench')}}</button></header><PhaseStatus :failure="failure||commandFailure" :loading="loading||commandBusy"/><p v-if="uncertain" role="alert">{{x('提交结果尚未确认；公司、原方案及金额已锁定。','Result unconfirmed; company, proposal and amounts are locked.')}} <button :disabled="commandBusy" @click="command.replay">{{x('重试原命令','Retry exact command')}}</button></p><label>{{x('公司','Company')}}<select v-model="company" :disabled="locked||loading" :aria-label="x('补发公司','Supplemental company')" @change="refresh"><option v-for="c in directory?.companies||[]" :key="c.id" :value="c.id">{{c.name}}</option></select></label><p v-if="directory&&!directory.companies.length">{{x('无完整公司工资权限。本人补发工资单请从“我的工资单”查看。','No full company payroll access. Find your own supplemental slips under My payslips.')}}</p><section v-if="company" class="wf-section"><h3>{{x('个人补发办理','Individual supplemental pay')}}</h3><p class="wf-hint">{{x('选择员工及原工资月份 → 填写遗漏项目和依据 → 提交审批 → 测算差额 → 确认 → 发布 → 登记付款。原工资未确认先重算；原金额正确仅未付清，继续原单付款。','Select employee and original month → Record omitted items and evidence → Approval → Calculate difference → Confirm → Publish → Register payment. Recalculate unconfirmed payroll; unpaid correct wages stay on the original payment record.')}}</p><div class="wf-grid"><label>{{x('员工','Employee')}}<select v-model="employee" :disabled="locked" :aria-label="x('补发员工','Supplemental employee')"><option value="">{{x('全部 / 新员工从申请入口选择','All / select a new person in the request')}}</option><option v-if="employee&&!people.some(p=>p.id===employee)" :value="employee">{{x('从原工资带入的员工','Employee from original payroll')}}</option><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>{{x('原工资月份','Original pay month')}}<input v-model="originMonth" type="month" :disabled="locked" :aria-label="x('原工资月份','Original pay month')"></label></div></section><nav v-if="company" class="wf-form-actions"><RouterLink :to="{path:base+'/pay-change-requests',query:{companyId:company,employeeId:employee||undefined,originMonth:originMonth||undefined,purpose:'supplemental'}}">{{x('新建／审核补发申请（沿用工资变更）','Create / review supplemental pay change')}}</RouterLink><RouterLink :to="{path:base+'/statutory-settlement',query:{companyId:company}}">{{x('法定事实、年度复核与缴纳','Statutory facts, annual review and remittance')}}</RouterLink></nav><section v-if="company" class="wf-section"><h3>{{x('由已批准内容建立独立批次','Create an independent batch from approved content')}}</h3><fieldset :disabled="locked||loading"><label>{{x('已批准补发申请','Approved supplemental request')}}<select v-model="requestId" :aria-label="x('已批准补发申请','Approved supplemental request')" @change="proposalId=''"><option value="">—</option><option v-for="r in approved" :key="r.id" :value="r.id">{{people.find(p=>p.id===r.employeeId)?.name||x('员工姓名待核对','Employee name unavailable')}} · {{r.effectiveDate}} · {{r.revision}}</option></select></label><label>{{x('精确补发方案','Exact supplemental proposal')}}<select v-model="proposalId" :aria-label="x('精确补发方案','Exact supplemental proposal')"><option value="">—</option><option v-for="p in request?.content.supplemental||[]" :key="p.id" :value="p.id">{{p.originMonth}} → {{p.settlementMonth}} · {{p.items.map(i=>i.label+' '+i.amount).join(' / ')}}</option></select></label><p v-if="request">{{x('批准修订／哈希','Approved revision / hash')}}: {{request.revision}} · {{request.hash}}</p><button :disabled="locked||!proposal" @click="create">{{x('建立补发批次','Create supplemental batch')}}</button></fieldset><p v-if="!approved.length&&!loading">{{x('暂无已批准补发；请先保存并提交工资变更申请。','No approved supplemental proposal. Save and submit a pay change first.')}}</p></section><div class="wf-table-wrap"><table><thead><tr><th>{{x('员工','Employee')}}</th><th>{{x('原贡献月／结算月','Original / settlement month')}}</th><th>{{x('批次状态','Batch state')}}</th><th>{{x('新增收入／员工现金应付','New gross / employee cash payable')}}</th><th></th></tr></thead><tbody><tr v-for="b in visibleRows" :key="b.id"><td>{{b.employeeName}}</td><td>{{b.originMonth}} / {{b.settlementMonth}}</td><td>{{supplementalState(b.status,english())}}</td><td>{{money(b.calculation?.grossDelta)}} / {{money(b.calculation?.employeeCashPayable)}}</td><td><button :disabled="locked||loading" @click="open(b.id)">{{x('查看补发','Review supplemental')}}</button></td></tr><tr v-if="!visibleRows.length&&!loading"><td colspan="5">{{x('暂无独立补发批次。','No supplemental batches.')}}</td></tr></tbody></table></div><article v-if="detail&&!loading" class="wf-section"><h3>{{detail.batch.employeeName}} · {{detail.batch.originMonth}} → {{detail.batch.settlementMonth}}</h3><p>{{x('批次状态','Batch state')}}: {{supplementalState(detail.batch.status,english())}} · {{x('精确批准修订','Exact approved revision')}} {{detail.batch.approval?.revision}} · {{detail.batch.approval?.hash}}</p><p v-if="detail.sourceChanged" role="alert">{{settlementIssue('SUPPLEMENTAL_SOURCE_CHANGED',english())}}</p><p>{{x('原来源（只读）','Original source (read only)')}}: {{supplementalSourceName(detail.batch.proposal.source.kind,english())}} · {{detail.batch.proposal.source.batchId||detail.batch.proposal.source.openingVersion||'—'}} · {{detail.batch.proposal.source.snapshotHash}}</p><RouterLink v-if="detail.batch.proposal.source.batchId" :to="base+'/payroll-batches/'+detail.batch.proposal.source.batchId">{{x('原工资单与原付款','Original payroll and payments')}}</RouterLink><WageEventReview :items="detail.batch.proposal.items" :month="detail.batch.originMonth"/><template v-if="detail.batch.calculation"><dl class="wf-details"><dt>{{x('新增收入／员工现金应付','New gross / employee cash payable')}}</dt><dd>{{money(detail.batch.calculation.grossDelta)}} / {{money(detail.batch.calculation.employeeCashPayable)}}</dd><dt>{{x('本次员工CPF扣款／CDAC扣款','Employee CPF / CDAC deducted this time')}}</dt><dd>{{money(detail.batch.calculation.employeeCpfDeduction)}} / {{money(detail.batch.calculation.cdacDeduction)}}</dd><dt>{{x('原单现金未付（继续原单付款）','Original cash remaining (pay on original payroll)')}}</dt><dd>{{money(detail.batch.calculation.originalCashRemaining)}}</dd><dt>{{x('公司SDL舍入差额（单独列示）','Company SDL rounding difference (separate)')}}</dt><dd>{{money(detail.batch.calculation.sdlRoundingDelta)}}</dd><dt>{{x('本次已付／剩余现金','Supplemental paid / cash remaining')}}</dt><dd>{{money(detail.paidAmount)}} / {{money(detail.remainingAmount)}}</dd></dl><p v-for="(code,i) in detail.batch.calculation.issues" :key="i" role="alert">{{settlementIssue(code,english())}} ({{code}})</p><StatutoryBalanceTable :balances="detail.batch.calculation.balances"/></template><section v-if="actions.length"><label>{{x('批次操作说明','Batch action note')}}<textarea v-model="note" maxlength="1000" :disabled="locked"/></label><div class="wf-form-actions"><button v-for="a in actions" :key="a" :disabled="locked" @click="action(a)">{{actionName(a)}}</button></div></section><p v-if="directory?.employeeId===detail.batch.employeeId" class="wf-hint">{{x('不能确认、发布或登记自己的工资付款。','You cannot confirm, publish or register your own payroll payment.')}}</p><section v-if="detail.payments.length"><h4>{{x('独立付款记录','Independent payment records')}}</h4><p v-for="p in detail.payments" :key="p.id">{{p.paymentDate}} · {{p.amount}} · {{p.reversesId?x('整笔冲正','Full reversal'):x('已登记','Recorded')}} · {{p.reference}}</p></section><SupplementalPaymentFields v-if="canPay" :key="detail.batch.id+'-'+detail.payments.length" :employee-id="detail.batch.employeeId" :settlement-month="detail.batch.settlementMonth" :remaining="detail.remainingAmount" :payments="detail.payments" :locked="locked" @save="payment"/></article></section></template>
<style scoped>p,dd{overflow-wrap:anywhere}nav{flex-wrap:wrap}fieldset{min-width:0}th,td{white-space:nowrap}</style>
